import { useEffect, useRef, useState, type RefObject } from 'react'

export interface ScrollIndicatorState {
  /** Thumb height as % of indicator track height. */
  thumbHeightPct: number
  /** Thumb top offset as % of indicator track height. */
  thumbTopPct: number
  /** True while the user is actively scrolling or just stopped. */
  visible: boolean
  /** True iff the container actually has overflow content to scroll. */
  hasOverflow: boolean
}

/**
 * Tracks scroll position on a container and exposes the metrics needed to
 * render a custom scroll indicator. Thumb size/position are returned as
 * percentages of the indicator's own track height, so the indicator element
 * can be sized/positioned with `top: X%` and `height: Y%` without the hook
 * needing to know how tall the indicator is.
 *
 * Auto-hide: visible flips to true on scroll, then back to false after the
 * idle timeout (default 800ms).
 *
 * Pass `null` (or a ref that stays null) to track the DOCUMENT scroller instead
 * of an element. That needs its own branch rather than a ref to
 * `documentElement`, because when the viewport is the scroller the scroll event
 * is fired at the `document` and never reaches the root element -- so measuring
 * would work and updating would not.
 */
export function useScrollIndicator(
  ref: RefObject<HTMLElement> | null,
  idleMs = 800,
): ScrollIndicatorState {
  const [state, setState] = useState<ScrollIndicatorState>({
    thumbHeightPct: 0,
    thumbTopPct: 0,
    visible: false,
    hasOverflow: false,
  })
  const hideTimer = useRef<number | null>(null)

  useEffect(() => {
    const doc = ref === null
    const el = doc ? document.documentElement : ref.current
    if (!el) return
    // The document scroller emits on `document`; an element emits on itself.
    const emitter: EventTarget = doc ? document : el

    const update = (showThumb: boolean) => {
      const { scrollTop, scrollHeight, clientHeight } = el
      const hasOverflow = scrollHeight > clientHeight + 1
      if (!hasOverflow) {
        setState(prev =>
          prev.hasOverflow ? { ...prev, hasOverflow: false, visible: false } : prev,
        )
        return
      }
      // thumb size = visible-fraction-of-content; thumb top moves linearly with
      // scrollTop. Expressed as percentages of the indicator's own track height
      // so the component can use CSS percent units without measuring itself.
      const thumbHeightPct = (clientHeight / scrollHeight) * 100
      const thumbTopPct = (scrollTop / scrollHeight) * 100
      setState({
        thumbHeightPct,
        thumbTopPct,
        visible: showThumb,
        hasOverflow: true,
      })
    }

    const onScroll = () => {
      update(true)
      if (hideTimer.current) window.clearTimeout(hideTimer.current)
      hideTimer.current = window.setTimeout(() => {
        setState(prev => (prev.visible ? { ...prev, visible: false } : prev))
      }, idleMs)
    }

    update(false)
    emitter.addEventListener('scroll', onScroll, { passive: true })
    const ro = new ResizeObserver(() => update(false))
    ro.observe(el)
    const mo = new MutationObserver(() => update(false))
    mo.observe(el, { childList: true, subtree: true })

    return () => {
      emitter.removeEventListener('scroll', onScroll)
      ro.disconnect()
      mo.disconnect()
      if (hideTimer.current) window.clearTimeout(hideTimer.current)
    }
  }, [ref, idleMs])

  return state
}
